-- 697: YATAN HASTA TABLOLARININ KİMLİK ÜRETEÇLERİNİ (sequence) TABLOYLA EŞİTLE.
--
-- SORUN: 695/696 ile gelen demo ve göç satırları KİMLİĞİ AÇIKÇA VERİLEREK
--   yazıldı (`insert ... (id, ...) values (9101, ...)`). PostgreSQL'de
--   `generated by default as identity` üreteci böyle bir yazımda İLERLEMEZ:
--   tablo 9105'e kadar doluyken üreteç hâlâ 1'i gösterir.
--
--   Sonuç sessiz bir zaman bombasıdır: uygulamadan açılan ilk yatışlar 1, 2,
--   3 ... diye gider (çalışır, kimse fark etmez) ve 9101'e gelindiğinde
--   "duplicate key value violates unique constraint" ile yatış açılamaz olur.
--   Hata, onu üreten insertten aylar sonra ve tamamen ilgisiz bir ekranda
--   çıkar.
--
-- ÇÖZÜM: her tablonun üretecini tablodaki en büyük kimliğe çek. Üreteç zaten
--   ileride ise GERİ ÇEKİLMEZ (geri çekmek, mevcut satırlarla çakışan kimlik
--   üretirdi). Yalnız üreteç ilerler, satıra dokunulmaz; tekrar
--   çalıştırılabilir.

do $$
declare
    t    text;
    dizi text;
    enb  bigint;
    simdi bigint;
begin
    foreach t in array array[
        'oda', 'yatak', 'yatis', 'yatis_yatak', 'yatis_order', 'order_uygulama',
        'yatis_izlem', 'yatis_sivi', 'yatis_risk', 'epikriz'
    ] loop
        -- Üreteç adı sabit kabul edilmez: pg_get_serial_sequence sütunun
        --   gerçekten hangi üretece bağlı olduğunu söyler (identity ya da
        --   serial, adı ne olursa olsun).
        dizi := pg_get_serial_sequence('public.' || t, 'id');
        if dizi is null then continue; end if;

        execute format('select coalesce(max(id), 0) from public.%I', t) into enb;
        if enb = 0 then continue; end if;

        execute format('select last_value from %s', dizi) into simdi;
        if simdi >= enb then continue; end if;

        perform setval(dizi, enb, true);
        raise notice 'sequence % -> %', dizi, enb;
    end loop;
end $$;
